  {
    "alert_id": "TDF_TOXICITY_BACK_PAIN_PHOSPHATE",
    "title": "TDF toxicity signs: back pain and low phosphate",
    "message": "Guidelines list lower back pain and muscle cramps as presenting signs of TDF toxicity (Fanconi syndrome, kidney injury); recommended evaluation includes LFTs and RFTs, with substitution to ABC if GFR <60 mL/min. Patient has 4 months of persistent lower back aching and heavy thighs, plus serum phosphate 0.78 mmol/L (low), trace proteinuria, and creatinine 112 umol/L. TDF is a known cause of proximal tubulopathy with phosphate wasting. Against drug attribution: occupational strain from truck driving is plausible, and creatinine is within normal limits. However, the combination of back pain, hypophosphataemia, and proteinuria is a compounding signal that warrants investigation. No eGFR was documented.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Calculate eGFR and repeat phosphate and urinalysis. If GFR <60 mL/min or phosphate remains low, substitute TDF with ABC per guidelines.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 24, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p24_c1"}
    ]
  },
  {
    "alert_id": "TDF_MONITORING_EGFR_GAP",
    "title": "Missing eGFR for TDF renal monitoring",
    "message": "Guidelines require serum creatinine and eGFR every 12 months for patients on TDF. Today's labs include creatinine 112 umol/L but no eGFR was calculated or documented. Trace proteinuria on dipstick provides additional reason to assess renal function quantitatively. The clinician's plan does not include renal function follow-up or repeat urinalysis.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Calculate eGFR from today's creatinine and document it. If eGFR <60 mL/min, evaluate for TDF substitution. Schedule repeat creatinine, eGFR, and urinalysis.",
    "citations": [
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "NSAID_TDF_NEPHROTOXICITY",
    "title": "Ibuprofen plus TDF increases renal risk",
    "message": "TDF is nephrotoxic and guidelines advise renal monitoring and substitution when renal function is impaired. Concurrent NSAID use compounds risk of acute kidney injury, particularly with existing trace proteinuria and borderline creatinine. The plan recommends PRN ibuprofen without renal caution. While ibuprofen is only intermittent, the patient already shows renal signals (proteinuria, low phosphate) that make NSAID use higher risk.",
    "issue_type": "compounding_risk",
    "severity": "moderate",
    "recommended_action": "Counsel patient to limit ibuprofen use. Consider alternative analgesia (e.g., paracetamol) and monitor renal function closely given TDF exposure and proteinuria.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"},
      {"page_number": 27, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p27_c2"}
    ]
  },
  {
    "alert_id": "EFV_FIRSTLINE_GUIDELINE",
    "title": "EFV-based regimen not current preferred first-line",
    "message": "Guidelines recommend DTG-based regimens (TDF+3TC+DTG) as preferred first-line for adults; EFV400 is an alternative when DTG is contraindicated. Patient is on EFV-based ART for 6 years, virologically suppressed and immunologically stable. No documented contraindication to DTG or reason for remaining on EFV is recorded. Given emerging TDF renal signals, a regimen review may be warranted.",
    "issue_type": "guideline_deviation",
    "severity": "low",
    "recommended_action": "Assess eligibility for transition to DTG-based regimen. If TDF renal toxicity is confirmed, consider ABC+3TC+DTG as substitute.",
    "citations": [
      {"page_number": 5, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p5_c3"}
    ]
  }
